 * Removal is a soft delete so the audit log keeps pointing at a real row.
 *
 * The member's out-of-office state leaves with them, in the same transaction:
 * their own absence is deleted, and any absence naming them as the delegate
 * keeps its window but loses the delegate — nothing may be redirected to
 * someone who is no longer here.
 */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const row = getDb().transaction((tx) => {
    const patch = archivePatch();
    const archived = tx
      .update(members)
      .set({ ...patch, status: "suspended" })
      .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
      .returning()
      .get();

    if (!archived) return undefined;

    tx.delete(memberAbsences)
      .where(
        and(
          orgPredicate(memberAbsences.orgId, orgId),
          eq(memberAbsences.userId, archived.userId),
        ),
      )
      .run();

    tx.update(memberAbsences)
      .set({ delegateUserId: null, updatedAt: patch.updatedAt })
      .where(
        and(
          orgPredicate(memberAbsences.orgId, orgId),
          eq(memberAbsences.delegateUserId, archived.userId),
        ),
      )
      .run();

    return archived;
  });

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

/** The stored absence, whether upcoming, running or already over. */
export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/** One absence per member per organization: writing again replaces it. */
export async function upsertAbsence(
  absence: MemberAbsence,
): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const values = {
    delegateUserId: absence.delegateUserId,
    startsAt: absence.startsAt,
    endsAt: absence.endsAt,
    note: absence.note,
    updatedAt: stamp,
  };

  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId: absence.orgId,
      userId: absence.userId,
      ...values,
      createdAt: stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: values,
    })
    .returning()
    .get();

  return toMemberAbsence(row);
}

/** Deleting an absence that does not exist is a no-op. */
export async function deleteAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}
