/**
 * Out-of-office absences: who may set them, and what being away redirects.
 *
 * `@/server/services/member-service` owns the absence itself; the issue
 * service, the notification fan-out and the overdue sweep consult it.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { setAbsenceSchema } from "@/schemas/member";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as memberRepo from "@/server/repositories/member-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, IsoTimestamp, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { NotificationKind } from "@/types/notification";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

const HOUR = 60 * 60 * 1000;

function stamp(offsetMs: number): IsoTimestamp {
  return new Date(Date.now() + offsetMs).toISOString() as IsoTimestamp;
}

/** An absence that is running right now. */
function away(tenant: Tenant, userId: UserId, delegateUserId: UserId | null) {
  return {
    orgId: tenant.org.id,
    userId,
    delegateUserId,
    startsAt: stamp(-HOUR),
    endsAt: stamp(HOUR),
    note: null,
  };
}

async function alertsFor(tenant: Tenant, recipientId: UserId, kind: NotificationKind) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: [kind],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("setting, reading and clearing an absence", () => {
  it("applies the schema defaults for delegate and note", () => {
    const tenantless = setAbsenceSchema.parse({
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      userId: "01HZZZAAAAAAAAAAAAAAAAAAA1",
      startsAt: "2026-06-01T00:00:00.000Z",
      endsAt: "2026-06-08T00:00:00.000Z",
    });
    expect(tenantless.delegateUserId).toBeNull();
    expect(tenantless.note).toBeNull();
    expect(
      setAbsenceSchema.safeParse({ ...tenantless, note: "x".repeat(201) }).success,
    ).toBe(false);
  });

  it("stores a member's own absence and returns exactly what was stored", async () => {
    const tenant = await createTenant("absence-own");
    const input = {
      ...away(tenant, tenant.userIds.viewer, tenant.userIds.member),
      note: "Back on Monday",
    };

    const stored = await memberService.setAbsence(tenant.actors.viewer, input);
    expect(stored).toEqual(input);

    // Anyone in the workspace can look it up.
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).resolves.toEqual(input);
  });

  it("replaces the previous absence when set again", async () => {
    const tenant = await createTenant("absence-replace");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const next = { ...away(tenant, tenant.userIds.member, null), note: "Changed plans" };
    await memberService.setAbsence(tenant.actors.member, next);

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(next);
  });

  it("returns a scheduled absence but not one that has ended", async () => {
    const tenant = await createTenant("absence-window");

    const upcoming = {
      ...away(tenant, tenant.userIds.member, null),
      startsAt: stamp(HOUR),
      endsAt: stamp(2 * HOUR),
    };
    await memberService.setAbsence(tenant.actors.member, upcoming);
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(upcoming);

    await memberService.setAbsence(tenant.actors.member, {
      ...upcoming,
      startsAt: stamp(-2 * HOUR),
      endsAt: stamp(-HOUR),
    });
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });

  it("clears an absence, and clearing nothing is fine", async () => {
    const tenant = await createTenant("absence-clear");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, null),
    );

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);

    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });

  it("lets only those who may change roles manage someone else's absence", async () => {
    const tenant = await createTenant("absence-permission");
    const target = away(tenant, tenant.userIds.viewer, null);

    await expect(
      memberService.setAbsence(tenant.actors.member, target),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(memberService.setAbsence(tenant.actors.admin, target)).resolves.toEqual(target);

    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer);
    await expect(
      memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.viewer),
    ).resolves.toBeNull();
  });

  it("rejects a window that does not end after it starts", async () => {
    const tenant = await createTenant("absence-range");
    const at = stamp(0);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        ...away(tenant, tenant.userIds.member, null),
        startsAt: at,
        endsAt: at,
      }),
    ).rejects.toThrow(/end after it starts/);
  });

  it("rejects a delegate who is the member, or not an active member", async () => {
    const tenant = await createTenant("absence-delegate");
    const other = await createTenant("absence-delegate-other");

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        away(tenant, tenant.userIds.member, tenant.userIds.member),
      ),
    ).rejects.toThrow(/own delegate/);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        away(tenant, tenant.userIds.member, other.userIds.admin),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("treats a removed member or an outsider as not found", async () => {
    const tenant = await createTenant("absence-notfound");
    const other = await createTenant("absence-notfound-other");

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    for (const userId of [tenant.userIds.viewer, other.userIds.member]) {
      await expect(
        memberService.setAbsence(tenant.actors.owner, away(tenant, userId, null)),
      ).rejects.toBeInstanceOf(NotFoundError);
      await expect(
        memberService.getAbsence(tenant.actors.owner, tenant.org.id, userId),
      ).rejects.toBeInstanceOf(NotFoundError);
      await expect(
        memberService.clearAbsence(tenant.actors.owner, tenant.org.id, userId),
      ).rejects.toBeInstanceOf(NotFoundError);
    }
  });

  it("refuses every operation on another workspace's orgId", async () => {
    const tenant = await createTenant("absence-scope");
    const other = await createTenant("absence-scope-other");

    await expect(
      memberService.setAbsence(tenant.actors.owner, away(other, other.userIds.member, null)),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.getAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.clearAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("assignments while away", () => {
  it("redirects an assignment to the delegate in every respect", async () => {
    const tenant = await createTenant("absence-assign");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.viewer),
    );

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Needs an owner" }),
    );

    const seen: Array<{ assigneeId: string; previousAssigneeId: string | null }> = [];
    detachers.push(
      subscribe("issue.assigned", (payload) => {
        seen.push({
          assigneeId: payload.assigneeId,
          previousAssigneeId: payload.previousAssigneeId,
        });
      }),
    );

    const assigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    expect(assigned.assigneeId).toBe(tenant.userIds.viewer);
    expect(seen).toEqual([{ assigneeId: tenant.userIds.viewer, previousAssigneeId: null }]);

    expect(await alertsFor(tenant, tenant.userIds.viewer, "issue_assigned")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_assigned")).toHaveLength(0);

    // The delegate is the assignee for permission purposes: a viewer may
    // update an issue only when it is theirs.
    const moved = await issueService.changeIssueStatus(tenant.actors.viewer, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });
    expect(moved.status).toBe("in_progress");
  });

  it("redirects the assignee of a newly created issue", async () => {
    const tenant = await createTenant("absence-create");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const seen: Array<string | null> = [];
    detachers.push(
      subscribe("issue.created", (payload) => {
        seen.push(payload.assigneeId);
      }),
    );

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Born delegated",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.admin);
    expect(seen).toEqual([tenant.userIds.admin]);
  });

  it("leaves a self-assignment alone", async () => {
    const tenant = await createTenant("absence-self");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Mine anyway",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(created.assigneeId).toBe(tenant.userIds.member);

    const other = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "I will take it" }),
    );
    const taken = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: other.id,
      assigneeId: tenant.userIds.member,
    });
    expect(taken.assigneeId).toBe(tenant.userIds.member);
  });

  it("never chains: an away delegate keeps the issue", async () => {
    const tenant = await createTenant("absence-chain");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    await memberService.setAbsence(
      tenant.actors.admin,
      away(tenant, tenant.userIds.admin, tenant.userIds.viewer),
    );

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "One hop only",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.admin);
  });

  it("does not redirect without a delegate, before the start or from the end on", async () => {
    const tenant = await createTenant("absence-not-away");
    const assign = async () => {
      const issue = await issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Who gets it",
          assigneeId: tenant.userIds.member,
        }),
      );
      return issue.assigneeId;
    };

    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, null),
    );
    expect(await assign()).toBe(tenant.userIds.member);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_assigned")).toHaveLength(0);

    const startsAt = "2026-06-01T00:00:00.000Z" as IsoTimestamp;
    const endsAt = "2026-06-08T00:00:00.000Z" as IsoTimestamp;
    await memberService.setAbsence(tenant.actors.member, {
      ...away(tenant, tenant.userIds.member, tenant.userIds.admin),
      startsAt,
      endsAt,
    });

    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date(new Date(startsAt).getTime() - 1));
      expect(await assign()).toBe(tenant.userIds.member);

      vi.setSystemTime(new Date(startsAt));
      expect(await assign()).toBe(tenant.userIds.admin);

      vi.setSystemTime(new Date(new Date(endsAt).getTime() - 1));
      expect(await assign()).toBe(tenant.userIds.admin);

      vi.setSystemTime(new Date(endsAt));
      expect(await assign()).toBe(tenant.userIds.member);
    } finally {
      vi.useRealTimers();
    }
  });

  it("keeps issues that were already the member's, and moves nothing back", async () => {
    const tenant = await createTenant("absence-existing");
    const mine = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already mine",
        assigneeId: tenant.userIds.member,
      }),
    );

    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    const redirected = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Arrived while away",
        assigneeId: tenant.userIds.member,
      }),
    );
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);

    const before = await issueService.getIssue(tenant.actors.owner, tenant.org.id, mine.id);
    const after = await issueService.getIssue(tenant.actors.owner, tenant.org.id, redirected.id);
    expect(before.issue.assigneeId).toBe(tenant.userIds.member);
    expect(after.issue.assigneeId).toBe(tenant.userIds.admin);
  });

  it("is scoped to the workspace the absence was set in", async () => {
    const tenant = await createTenant("absence-tenant-a");
    const other = await createTenant("absence-tenant-b");

    // The same user belongs to both workspaces, but is away in only one.
    await memberRepo.insertMember(other.org.id, tenant.userIds.member, "member", null);
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const issue = await issueService.createIssue(
      other.actors.owner,
      issueInput(other.org.id, other.project.id, {
        title: "Other workspace",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.member);

    await expect(
      memberService.getAbsence(other.actors.owner, other.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });
});

describe("alerts while away", () => {
  it("sends the overdue alert to the delegate, judged at the sweep's clock", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("absence-overdue");
    await usageRepo.recomputeUsage(tenant.org.id);

    const make = (title: string) =>
      issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, {
          title,
          assigneeId: tenant.userIds.member,
          dueAt: "2026-01-01T00:00:00.000Z",
        }),
      );
    const first = await make("Late during the absence");

    const startsAt = "2026-06-01T00:00:00.000Z" as IsoTimestamp;
    const endsAt = "2026-06-08T00:00:00.000Z" as IsoTimestamp;
    await memberService.setAbsence(tenant.actors.member, {
      ...away(tenant, tenant.userIds.member, tenant.userIds.admin),
      startsAt,
      endsAt,
    });

    const seen: Array<string | null> = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        if (payload.orgId === tenant.org.id) seen.push(payload.assigneeId);
      }),
    );

    await runOverdueIssueJob(new Date(startsAt));

    // The sweep still announces the real assignee; only the alert moves.
    expect(seen).toEqual([tenant.userIds.member]);
    const stored = await issueService.getIssue(tenant.actors.owner, tenant.org.id, first.id);
    expect(stored.issue.assigneeId).toBe(tenant.userIds.member);
    expect(await alertsFor(tenant, tenant.userIds.admin, "issue_overdue")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(0);

    // Once the absence has ended the alert reaches the member again.
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    await make("Late after the absence");
    await memberService.setAbsence(tenant.actors.owner, {
      ...away(tenant, tenant.userIds.member, tenant.userIds.admin),
      startsAt,
      endsAt,
    });
    await runOverdueIssueJob(new Date(endsAt));

    expect(await alertsFor(tenant, tenant.userIds.admin, "issue_overdue")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(1);
  });

  it("keeps the overdue alert with an away member who has no delegate", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("absence-overdue-solo");
    await usageRepo.recomputeUsage(tenant.org.id);

    await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late, nobody covering",
        assigneeId: tenant.userIds.member,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
    );
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, null),
    );

    await runOverdueIssueJob(new Date());

    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(1);
  });

  it("alerts both the mentioned member and their delegate, once each", async () => {
    const tenant = await createTenant("absence-mention");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Talk here" }),
    );

    // The delegate is also mentioned directly: still one alert.
    await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ping",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member, tenant.userIds.admin],
    });

    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.viewer, "comment_mention")).toHaveLength(0);
  });

  it("never alerts a delegate who wrote the comment, and honours their preferences", async () => {
    const tenant = await createTenant("absence-mention-rules");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Rules still apply" }),
    );

    await commentService.createComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "covering for you",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member],
    });
    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(0);
    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(1);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "comment_mention",
      inApp: false,
      email: false,
      digestOnly: false,
    });
    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      occurredAt: stamp(0),
      commentId: "cmt-absence-muted" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.member],
    });
    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(0);
    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(2);
  });
});

describe("membership changes", () => {
  it("drops the delegation when the delegate is removed, keeping the absence", async () => {
    const tenant = await createTenant("absence-delegate-leaves");
    const absence = away(tenant, tenant.userIds.member, tenant.userIds.viewer);
    await memberService.setAbsence(tenant.actors.member, absence);

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual({ ...absence, delegateUserId: null });

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Nobody to redirect to",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.member);
  });

  it("removes a member's own absence along with the member", async () => {
    const tenant = await createTenant("absence-member-leaves");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!member) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    await expect(memberRepo.findAbsence(tenant.org.id, tenant.userIds.member)).resolves.toBeNull();
  });
});

toolUseResult.content:
/**
 * Out-of-office absences: who may set them, and what being away redirects.
 *
 * `@/server/services/member-service` owns the absence itself; the issue
 * service, the notification fan-out and the overdue sweep consult it.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { setAbsenceSchema } from "@/schemas/member";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as memberRepo from "@/server/repositories/member-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, IsoTimestamp, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { NotificationKind } from "@/types/notification";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

const HOUR = 60 * 60 * 1000;

function stamp(offsetMs: number): IsoTimestamp {
  return new Date(Date.now() + offsetMs).toISOString() as IsoTimestamp;
}

/** An absence that is running right now. */
function away(tenant: Tenant, userId: UserId, delegateUserId: UserId | null) {
  return {
    orgId: tenant.org.id,
    userId,
    delegateUserId,
    startsAt: stamp(-HOUR),
    endsAt: stamp(HOUR),
    note: null,
  };
}

async function alertsFor(tenant: Tenant, recipientId: UserId, kind: NotificationKind) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: [kind],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("setting, reading and clearing an absence", () => {
  it("applies the schema defaults for delegate and note", () => {
    const tenantless = setAbsenceSchema.parse({
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      userId: "01HZZZAAAAAAAAAAAAAAAAAAA1",
      startsAt: "2026-06-01T00:00:00.000Z",
      endsAt: "2026-06-08T00:00:00.000Z",
    });
    expect(tenantless.delegateUserId).toBeNull();
    expect(tenantless.note).toBeNull();
    expect(
      setAbsenceSchema.safeParse({ ...tenantless, note: "x".repeat(201) }).success,
    ).toBe(false);
  });

  it("stores a member's own absence and returns exactly what was stored", async () => {
    const tenant = await createTenant("absence-own");
    const input = {
      ...away(tenant, tenant.userIds.viewer, tenant.userIds.member),
      note: "Back on Monday",
    };

    const stored = await memberService.setAbsence(tenant.actors.viewer, input);
    expect(stored).toEqual(input);

    // Anyone in the workspace can look it up.
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).resolves.toEqual(input);
  });

  it("replaces the previous absence when set again", async () => {
    const tenant = await createTenant("absence-replace");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const next = { ...away(tenant, tenant.userIds.member, null), note: "Changed plans" };
    await memberService.setAbsence(tenant.actors.member, next);

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(next);
  });

  it("returns a scheduled absence but not one that has ended", async () => {
    const tenant = await createTenant("absence-window");

    const upcoming = {
      ...away(tenant, tenant.userIds.member, null),
      startsAt: stamp(HOUR),
      endsAt: stamp(2 * HOUR),
    };
    await memberService.setAbsence(tenant.actors.member, upcoming);
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(upcoming);

    await memberService.setAbsence(tenant.actors.member, {
      ...upcoming,
      startsAt: stamp(-2 * HOUR),
      endsAt: stamp(-HOUR),
    });
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });

  it("clears an absence, and clearing nothing is fine", async () => {
    const tenant = await createTenant("absence-clear");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, null),
    );

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);

    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });

  it("lets only those who may change roles manage someone else's absence", async () => {
    const tenant = await createTenant("absence-permission");
    const target = away(tenant, tenant.userIds.viewer, null);

    await expect(
      memberService.setAbsence(tenant.actors.member, target),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(memberService.setAbsence(tenant.actors.admin, target)).resolves.toEqual(target);

    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer);
    await expect(
      memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.viewer),
    ).resolves.toBeNull();
  });

  it("rejects a window that does not end after it starts", async () => {
    const tenant = await createTenant("absence-range");
    const at = stamp(0);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        ...away(tenant, tenant.userIds.member, null),
        startsAt: at,
        endsAt: at,
      }),
    ).rejects.toThrow(/end after it starts/);
  });

  it("rejects a delegate who is the member, or not an active member", async () => {
    const tenant = await createTenant("absence-delegate");
    const other = await createTenant("absence-delegate-other");

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        away(tenant, tenant.userIds.member, tenant.userIds.member),
      ),
    ).rejects.toThrow(/own delegate/);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        away(tenant, tenant.userIds.member, other.userIds.admin),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("treats a removed member or an outsider as not found", async () => {
    const tenant = await createTenant("absence-notfound");
    const other = await createTenant("absence-notfound-other");

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    for (const userId of [tenant.userIds.viewer, other.userIds.member]) {
      await expect(
        memberService.setAbsence(tenant.actors.owner, away(tenant, userId, null)),
      ).rejects.toBeInstanceOf(NotFoundError);
      await expect(
        memberService.getAbsence(tenant.actors.owner, tenant.org.id, userId),
      ).rejects.toBeInstanceOf(NotFoundError);
      await expect(
        memberService.clearAbsence(tenant.actors.owner, tenant.org.id, userId),
      ).rejects.toBeInstanceOf(NotFoundError);
    }
  });

  it("refuses every operation on another workspace's orgId", async () => {
    const tenant = await createTenant("absence-scope");
    const other = await createTenant("absence-scope-other");

    await expect(
      memberService.setAbsence(tenant.actors.owner, away(other, other.userIds.member, null)),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.getAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.clearAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("assignments while away", () => {
  it("redirects an assignment to the delegate in every respect", async () => {
    const tenant = await createTenant("absence-assign");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.viewer),
    );

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Needs an owner" }),
    );

    const seen: Array<{ assigneeId: string; previousAssigneeId: string | null }> = [];
    detachers.push(
      subscribe("issue.assigned", (payload) => {
        seen.push({
          assigneeId: payload.assigneeId,
          previousAssigneeId: payload.previousAssigneeId,
        });
      }),
    );

    const assigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    expect(assigned.assigneeId).toBe(tenant.userIds.viewer);
    expect(seen).toEqual([{ assigneeId: tenant.userIds.viewer, previousAssigneeId: null }]);

    expect(await alertsFor(tenant, tenant.userIds.viewer, "issue_assigned")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_assigned")).toHaveLength(0);

    // The delegate is the assignee for permission purposes: a viewer may
    // update an issue only when it is theirs.
    const moved = await issueService.changeIssueStatus(tenant.actors.viewer, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });
    expect(moved.status).toBe("in_progress");
  });

  it("redirects the assignee of a newly created issue", async () => {
    const tenant = await createTenant("absence-create");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const seen: Array<string | null> = [];
    detachers.push(
      subscribe("issue.created", (payload) => {
        seen.push(payload.assigneeId);
      }),
    );

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Born delegated",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.admin);
    expect(seen).toEqual([tenant.userIds.admin]);
  });

  it("leaves a self-assignment alone", async () => {
    const tenant = await createTenant("absence-self");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Mine anyway",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(created.assigneeId).toBe(tenant.userIds.member);

    const other = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "I will take it" }),
    );
    const taken = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: other.id,
      assigneeId: tenant.userIds.member,
    });
    expect(taken.assigneeId).toBe(tenant.userIds.member);
  });

  it("never chains: an away delegate keeps the issue", async () => {
    const tenant = await createTenant("absence-chain");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    await memberService.setAbsence(
      tenant.actors.admin,
      away(tenant, tenant.userIds.admin, tenant.userIds.viewer),
    );

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "One hop only",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.admin);
  });

  it("does not redirect without a delegate, before the start or from the end on", async () => {
    const tenant = await createTenant("absence-not-away");
    const assign = async () => {
      const issue = await issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Who gets it",
          assigneeId: tenant.userIds.member,
        }),
      );
      return issue.assigneeId;
    };

    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, null),
    );
    expect(await assign()).toBe(tenant.userIds.member);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_assigned")).toHaveLength(0);

    const startsAt = "2026-06-01T00:00:00.000Z" as IsoTimestamp;
    const endsAt = "2026-06-08T00:00:00.000Z" as IsoTimestamp;
    await memberService.setAbsence(tenant.actors.member, {
      ...away(tenant, tenant.userIds.member, tenant.userIds.admin),
      startsAt,
      endsAt,
    });

    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date(new Date(startsAt).getTime() - 1));
      expect(await assign()).toBe(tenant.userIds.member);

      vi.setSystemTime(new Date(startsAt));
      expect(await assign()).toBe(tenant.userIds.admin);

      vi.setSystemTime(new Date(new Date(endsAt).getTime() - 1));
      expect(await assign()).toBe(tenant.userIds.admin);

      vi.setSystemTime(new Date(endsAt));
      expect(await assign()).toBe(tenant.userIds.member);
    } finally {
      vi.useRealTimers();
    }
  });

  it("keeps issues that were already the member's, and moves nothing back", async () => {
    const tenant = await createTenant("absence-existing");
    const mine = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already mine",
        assigneeId: tenant.userIds.member,
      }),
    );

    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    const redirected = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Arrived while away",
        assigneeId: tenant.userIds.member,
      }),
    );
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);

    const before = await issueService.getIssue(tenant.actors.owner, tenant.org.id, mine.id);
    const after = await issueService.getIssue(tenant.actors.owner, tenant.org.id, redirected.id);
    expect(before.issue.assigneeId).toBe(tenant.userIds.member);
    expect(after.issue.assigneeId).toBe(tenant.userIds.admin);
  });

  it("is scoped to the workspace the absence was set in", async () => {
    const tenant = await createTenant("absence-tenant-a");
    const other = await createTenant("absence-tenant-b");

    // The same user belongs to both workspaces, but is away in only one.
    await memberRepo.insertMember(other.org.id, tenant.userIds.member, "member", null);
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const issue = await issueService.createIssue(
      other.actors.owner,
      issueInput(other.org.id, other.project.id, {
        title: "Other workspace",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.member);

    await expect(
      memberService.getAbsence(other.actors.owner, other.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });
});

describe("alerts while away", () => {
  it("sends the overdue alert to the delegate, judged at the sweep's clock", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("absence-overdue");
    await usageRepo.recomputeUsage(tenant.org.id);

    const make = (title: string) =>
      issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, {
          title,
          assigneeId: tenant.userIds.member,
          dueAt: "2026-01-01T00:00:00.000Z",
        }),
      );
    const first = await make("Late during the absence");

    const startsAt = "2026-06-01T00:00:00.000Z" as IsoTimestamp;
    const endsAt = "2026-06-08T00:00:00.000Z" as IsoTimestamp;
    await memberService.setAbsence(tenant.actors.member, {
      ...away(tenant, tenant.userIds.member, tenant.userIds.admin),
      startsAt,
      endsAt,
    });

    const seen: Array<string | null> = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        if (payload.orgId === tenant.org.id) seen.push(payload.assigneeId);
      }),
    );

    await runOverdueIssueJob(new Date(startsAt));

    // The sweep still announces the real assignee; only the alert moves.
    expect(seen).toEqual([tenant.userIds.member]);
    const stored = await issueService.getIssue(tenant.actors.owner, tenant.org.id, first.id);
    expect(stored.issue.assigneeId).toBe(tenant.userIds.member);
    expect(await alertsFor(tenant, tenant.userIds.admin, "issue_overdue")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(0);

    // Once the absence has ended the alert reaches the member again.
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    await make("Late after the absence");
    await memberService.setAbsence(tenant.actors.owner, {
      ...away(tenant, tenant.userIds.member, tenant.userIds.admin),
      startsAt,
      endsAt,
    });
    await runOverdueIssueJob(new Date(endsAt));

    expect(await alertsFor(tenant, tenant.userIds.admin, "issue_overdue")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(1);
  });

  it("keeps the overdue alert with an away member who has no delegate", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("absence-overdue-solo");
    await usageRepo.recomputeUsage(tenant.org.id);

    await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late, nobody covering",
        assigneeId: tenant.userIds.member,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
    );
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, null),
    );

    await runOverdueIssueJob(new Date());

    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(1);
  });

  it("alerts both the mentioned member and their delegate, once each", async () => {
    const tenant = await createTenant("absence-mention");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Talk here" }),
    );

    // The delegate is also mentioned directly: still one alert.
    await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ping",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member, tenant.userIds.admin],
    });

    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.viewer, "comment_mention")).toHaveLength(0);
  });

  it("never alerts a delegate who wrote the comment, and honours their preferences", async () => {
    const tenant = await createTenant("absence-mention-rules");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Rules still apply" }),
    );

    await commentService.createComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "covering for you",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member],
    });
    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(0);
    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(1);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "comment_mention",
      inApp: false,
      email: false,
      digestOnly: false,
    });
    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      occurredAt: stamp(0),
      commentId: "cmt-absence-muted" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.member],
    });
    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(0);
    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(2);
  });
});

describe("membership changes", () => {
  it("drops the delegation when the delegate is removed, keeping the absence", async () => {
    const tenant = await createTenant("absence-delegate-leaves");
    const absence = away(tenant, tenant.userIds.member, tenant.userIds.viewer);
    await memberService.setAbsence(tenant.actors.member, absence);

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual({ ...absence, delegateUserId: null });

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Nobody to redirect to",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.member);
  });

  it("removes a member's own absence along with the member", async () => {
    const tenant = await createTenant("absence-member-leaves");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!member) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    await expect(memberRepo.findAbsence(tenant.org.id, tenant.userIds.member)).resolves.toBeNull();
  });
});

input.content:
/**
 * Out-of-office absences: who may set them, and what being away redirects.
 *
 * `@/server/services/member-service` owns the absence itself; the issue
 * service, the notification fan-out and the overdue sweep consult it.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { emit, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { setAbsenceSchema } from "@/schemas/member";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as memberRepo from "@/server/repositories/member-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, IsoTimestamp, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { NotificationKind } from "@/types/notification";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

const HOUR = 60 * 60 * 1000;

function stamp(offsetMs: number): IsoTimestamp {
  return new Date(Date.now() + offsetMs).toISOString() as IsoTimestamp;
}

/** An absence that is running right now. */
function away(tenant: Tenant, userId: UserId, delegateUserId: UserId | null) {
  return {
    orgId: tenant.org.id,
    userId,
    delegateUserId,
    startsAt: stamp(-HOUR),
    endsAt: stamp(HOUR),
    note: null,
  };
}

async function alertsFor(tenant: Tenant, recipientId: UserId, kind: NotificationKind) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: [kind],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("setting, reading and clearing an absence", () => {
  it("applies the schema defaults for delegate and note", () => {
    const tenantless = setAbsenceSchema.parse({
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      userId: "01HZZZAAAAAAAAAAAAAAAAAAA1",
      startsAt: "2026-06-01T00:00:00.000Z",
      endsAt: "2026-06-08T00:00:00.000Z",
    });
    expect(tenantless.delegateUserId).toBeNull();
    expect(tenantless.note).toBeNull();
    expect(
      setAbsenceSchema.safeParse({ ...tenantless, note: "x".repeat(201) }).success,
    ).toBe(false);
  });

  it("stores a member's own absence and returns exactly what was stored", async () => {
    const tenant = await createTenant("absence-own");
    const input = {
      ...away(tenant, tenant.userIds.viewer, tenant.userIds.member),
      note: "Back on Monday",
    };

    const stored = await memberService.setAbsence(tenant.actors.viewer, input);
    expect(stored).toEqual(input);

    // Anyone in the workspace can look it up.
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).resolves.toEqual(input);
  });

  it("replaces the previous absence when set again", async () => {
    const tenant = await createTenant("absence-replace");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const next = { ...away(tenant, tenant.userIds.member, null), note: "Changed plans" };
    await memberService.setAbsence(tenant.actors.member, next);

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(next);
  });

  it("returns a scheduled absence but not one that has ended", async () => {
    const tenant = await createTenant("absence-window");

    const upcoming = {
      ...away(tenant, tenant.userIds.member, null),
      startsAt: stamp(HOUR),
      endsAt: stamp(2 * HOUR),
    };
    await memberService.setAbsence(tenant.actors.member, upcoming);
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual(upcoming);

    await memberService.setAbsence(tenant.actors.member, {
      ...upcoming,
      startsAt: stamp(-2 * HOUR),
      endsAt: stamp(-HOUR),
    });
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });

  it("clears an absence, and clearing nothing is fine", async () => {
    const tenant = await createTenant("absence-clear");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, null),
    );

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);

    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });

  it("lets only those who may change roles manage someone else's absence", async () => {
    const tenant = await createTenant("absence-permission");
    const target = away(tenant, tenant.userIds.viewer, null);

    await expect(
      memberService.setAbsence(tenant.actors.member, target),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(memberService.setAbsence(tenant.actors.admin, target)).resolves.toEqual(target);

    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer);
    await expect(
      memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.viewer),
    ).resolves.toBeNull();
  });

  it("rejects a window that does not end after it starts", async () => {
    const tenant = await createTenant("absence-range");
    const at = stamp(0);

    await expect(
      memberService.setAbsence(tenant.actors.member, {
        ...away(tenant, tenant.userIds.member, null),
        startsAt: at,
        endsAt: at,
      }),
    ).rejects.toThrow(/end after it starts/);
  });

  it("rejects a delegate who is the member, or not an active member", async () => {
    const tenant = await createTenant("absence-delegate");
    const other = await createTenant("absence-delegate-other");

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        away(tenant, tenant.userIds.member, tenant.userIds.member),
      ),
    ).rejects.toThrow(/own delegate/);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        away(tenant, tenant.userIds.member, other.userIds.admin),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("treats a removed member or an outsider as not found", async () => {
    const tenant = await createTenant("absence-notfound");
    const other = await createTenant("absence-notfound-other");

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    for (const userId of [tenant.userIds.viewer, other.userIds.member]) {
      await expect(
        memberService.setAbsence(tenant.actors.owner, away(tenant, userId, null)),
      ).rejects.toBeInstanceOf(NotFoundError);
      await expect(
        memberService.getAbsence(tenant.actors.owner, tenant.org.id, userId),
      ).rejects.toBeInstanceOf(NotFoundError);
      await expect(
        memberService.clearAbsence(tenant.actors.owner, tenant.org.id, userId),
      ).rejects.toBeInstanceOf(NotFoundError);
    }
  });

  it("refuses every operation on another workspace's orgId", async () => {
    const tenant = await createTenant("absence-scope");
    const other = await createTenant("absence-scope-other");

    await expect(
      memberService.setAbsence(tenant.actors.owner, away(other, other.userIds.member, null)),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.getAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.clearAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("assignments while away", () => {
  it("redirects an assignment to the delegate in every respect", async () => {
    const tenant = await createTenant("absence-assign");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.viewer),
    );

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Needs an owner" }),
    );

    const seen: Array<{ assigneeId: string; previousAssigneeId: string | null }> = [];
    detachers.push(
      subscribe("issue.assigned", (payload) => {
        seen.push({
          assigneeId: payload.assigneeId,
          previousAssigneeId: payload.previousAssigneeId,
        });
      }),
    );

    const assigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.member,
    });

    expect(assigned.assigneeId).toBe(tenant.userIds.viewer);
    expect(seen).toEqual([{ assigneeId: tenant.userIds.viewer, previousAssigneeId: null }]);

    expect(await alertsFor(tenant, tenant.userIds.viewer, "issue_assigned")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_assigned")).toHaveLength(0);

    // The delegate is the assignee for permission purposes: a viewer may
    // update an issue only when it is theirs.
    const moved = await issueService.changeIssueStatus(tenant.actors.viewer, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });
    expect(moved.status).toBe("in_progress");
  });

  it("redirects the assignee of a newly created issue", async () => {
    const tenant = await createTenant("absence-create");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const seen: Array<string | null> = [];
    detachers.push(
      subscribe("issue.created", (payload) => {
        seen.push(payload.assigneeId);
      }),
    );

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Born delegated",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.admin);
    expect(seen).toEqual([tenant.userIds.admin]);
  });

  it("leaves a self-assignment alone", async () => {
    const tenant = await createTenant("absence-self");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Mine anyway",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(created.assigneeId).toBe(tenant.userIds.member);

    const other = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "I will take it" }),
    );
    const taken = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: other.id,
      assigneeId: tenant.userIds.member,
    });
    expect(taken.assigneeId).toBe(tenant.userIds.member);
  });

  it("never chains: an away delegate keeps the issue", async () => {
    const tenant = await createTenant("absence-chain");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    await memberService.setAbsence(
      tenant.actors.admin,
      away(tenant, tenant.userIds.admin, tenant.userIds.viewer),
    );

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "One hop only",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.admin);
  });

  it("does not redirect without a delegate, before the start or from the end on", async () => {
    const tenant = await createTenant("absence-not-away");
    const assign = async () => {
      const issue = await issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Who gets it",
          assigneeId: tenant.userIds.member,
        }),
      );
      return issue.assigneeId;
    };

    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, null),
    );
    expect(await assign()).toBe(tenant.userIds.member);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_assigned")).toHaveLength(0);

    const startsAt = "2026-06-01T00:00:00.000Z" as IsoTimestamp;
    const endsAt = "2026-06-08T00:00:00.000Z" as IsoTimestamp;
    await memberService.setAbsence(tenant.actors.member, {
      ...away(tenant, tenant.userIds.member, tenant.userIds.admin),
      startsAt,
      endsAt,
    });

    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date(new Date(startsAt).getTime() - 1));
      expect(await assign()).toBe(tenant.userIds.member);

      vi.setSystemTime(new Date(startsAt));
      expect(await assign()).toBe(tenant.userIds.admin);

      vi.setSystemTime(new Date(new Date(endsAt).getTime() - 1));
      expect(await assign()).toBe(tenant.userIds.admin);

      vi.setSystemTime(new Date(endsAt));
      expect(await assign()).toBe(tenant.userIds.member);
    } finally {
      vi.useRealTimers();
    }
  });

  it("keeps issues that were already the member's, and moves nothing back", async () => {
    const tenant = await createTenant("absence-existing");
    const mine = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already mine",
        assigneeId: tenant.userIds.member,
      }),
    );

    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    const redirected = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Arrived while away",
        assigneeId: tenant.userIds.member,
      }),
    );
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);

    const before = await issueService.getIssue(tenant.actors.owner, tenant.org.id, mine.id);
    const after = await issueService.getIssue(tenant.actors.owner, tenant.org.id, redirected.id);
    expect(before.issue.assigneeId).toBe(tenant.userIds.member);
    expect(after.issue.assigneeId).toBe(tenant.userIds.admin);
  });

  it("is scoped to the workspace the absence was set in", async () => {
    const tenant = await createTenant("absence-tenant-a");
    const other = await createTenant("absence-tenant-b");

    // The same user belongs to both workspaces, but is away in only one.
    await memberRepo.insertMember(other.org.id, tenant.userIds.member, "member", null);
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const issue = await issueService.createIssue(
      other.actors.owner,
      issueInput(other.org.id, other.project.id, {
        title: "Other workspace",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.member);

    await expect(
      memberService.getAbsence(other.actors.owner, other.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });
});

describe("alerts while away", () => {
  it("sends the overdue alert to the delegate, judged at the sweep's clock", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("absence-overdue");
    await usageRepo.recomputeUsage(tenant.org.id);

    const make = (title: string) =>
      issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, {
          title,
          assigneeId: tenant.userIds.member,
          dueAt: "2026-01-01T00:00:00.000Z",
        }),
      );
    const first = await make("Late during the absence");

    const startsAt = "2026-06-01T00:00:00.000Z" as IsoTimestamp;
    const endsAt = "2026-06-08T00:00:00.000Z" as IsoTimestamp;
    await memberService.setAbsence(tenant.actors.member, {
      ...away(tenant, tenant.userIds.member, tenant.userIds.admin),
      startsAt,
      endsAt,
    });

    const seen: Array<string | null> = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        if (payload.orgId === tenant.org.id) seen.push(payload.assigneeId);
      }),
    );

    await runOverdueIssueJob(new Date(startsAt));

    // The sweep still announces the real assignee; only the alert moves.
    expect(seen).toEqual([tenant.userIds.member]);
    const stored = await issueService.getIssue(tenant.actors.owner, tenant.org.id, first.id);
    expect(stored.issue.assigneeId).toBe(tenant.userIds.member);
    expect(await alertsFor(tenant, tenant.userIds.admin, "issue_overdue")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(0);

    // Once the absence has ended the alert reaches the member again.
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    await make("Late after the absence");
    await memberService.setAbsence(tenant.actors.owner, {
      ...away(tenant, tenant.userIds.member, tenant.userIds.admin),
      startsAt,
      endsAt,
    });
    await runOverdueIssueJob(new Date(endsAt));

    expect(await alertsFor(tenant, tenant.userIds.admin, "issue_overdue")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(1);
  });

  it("keeps the overdue alert with an away member who has no delegate", async () => {
    resetOverdueTracking();
    const tenant = await createTenant("absence-overdue-solo");
    await usageRepo.recomputeUsage(tenant.org.id);

    await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late, nobody covering",
        assigneeId: tenant.userIds.member,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
    );
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, null),
    );

    await runOverdueIssueJob(new Date());

    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(1);
  });

  it("alerts both the mentioned member and their delegate, once each", async () => {
    const tenant = await createTenant("absence-mention");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Talk here" }),
    );

    // The delegate is also mentioned directly: still one alert.
    await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ping",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member, tenant.userIds.admin],
    });

    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.viewer, "comment_mention")).toHaveLength(0);
  });

  it("never alerts a delegate who wrote the comment, and honours their preferences", async () => {
    const tenant = await createTenant("absence-mention-rules");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Rules still apply" }),
    );

    await commentService.createComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "covering for you",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member],
    });
    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(0);
    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(1);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "comment_mention",
      inApp: false,
      email: false,
      digestOnly: false,
    });
    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      occurredAt: stamp(0),
      commentId: "cmt-absence-muted" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.member],
    });
    expect(await alertsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(0);
    expect(await alertsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(2);
  });
});

describe("membership changes", () => {
  it("drops the delegation when the delegate is removed, keeping the absence", async () => {
    const tenant = await createTenant("absence-delegate-leaves");
    const absence = away(tenant, tenant.userIds.member, tenant.userIds.viewer);
    await memberService.setAbsence(tenant.actors.member, absence);

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toEqual({ ...absence, delegateUserId: null });

    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Nobody to redirect to",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.member);
  });

  it("removes a member's own absence along with the member", async () => {
    const tenant = await createTenant("absence-member-leaves");
    await memberService.setAbsence(
      tenant.actors.member,
      away(tenant, tenant.userIds.member, tenant.userIds.admin),
    );

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!member) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    await expect(memberRepo.findAbsence(tenant.org.id, tenant.userIds.member)).resolves.toBeNull();
  });
});

