/**
 * Membership and role changes, including the invariant that an organization always keeps one owner.
 * Also owns out-of-office absences and the one question the rest of the server asks about them:
 * "who stands in for this member right now?" (`resolveDelegate`).
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hasRoleAtLeast
 */
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import { hasRoleAtLeast } from "@/types/member";
import {
  actorEnvelope,
  memberResource,
  NotFoundError,
  orgResource,
  requireFound,
} from "./_support";
import type {
  ListMembersInput,
  RemoveMemberInput,
  SetAbsenceInput,
  UpdateMemberRoleInput,
} from "@/schemas/member";
import type { MemberId, OrgId, Page, UserId } from "@/types/common";
import type {
  Actor,
  Member,
  MemberAbsence,
  MemberWithUser,
  Role,
} from "@/types/member";

/** How many members are scanned when counting the remaining owners. */
const OWNER_SCAN_LIMIT = 100;

export async function listMembers(
  actor: Actor,
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "member:read", {
    kind: "organization",
    orgId: input.orgId,
  });
  return memberRepo.listMembers(input);
}

/**
 * Role changes carry two rules the permission matrix cannot express:
 * nobody may grant a role above their own, and the last owner may not be
 * demoted. Both are checked after `can()` has had its say.
 */
export async function updateMemberRole(
  actor: Actor,
  input: UpdateMemberRoleInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:update_role", memberResource(member));

  if (!hasRoleAtLeast(actor.role, input.role)) {
    throw new Error(
      `A ${actor.role} cannot grant the ${input.role} role`,
    );
  }

  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);

  const updated = await memberRepo.updateMemberRole(
    input.orgId,
    input.memberId,
    input.role,
  );

  await emit("member.role_changed", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    from: member.role,
    to: updated.role,
  });

  return updated;
}

/**
 * Removal is a soft delete, and it is subject to the same last-owner rule as a
 * demotion — a removed owner is a demotion to "no role at all".
 */
export async function removeMember(
  actor: Actor,
  input: RemoveMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:remove", memberResource(member));

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  await emit("member.removed", {
    ...actorEnvelope(actor),
    memberId: removed.id,
    userId: removed.userId,
  });

  return removed;
}

/**
 * Marks a member away between two instants and optionally names a stand-in.
 * Setting it again replaces the previous absence. Members manage their own;
 * managing someone else's takes the right to change member roles.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  assertCanManageAbsence(actor, member);

  if (!(toInstant(input.endsAt) > toInstant(input.startsAt))) {
    throw new Error("An absence must end after it starts");
  }

  const delegateUserId = input.delegateUserId ?? null;
  if (delegateUserId !== null) {
    if (delegateUserId === member.userId) {
      throw new Error("A member cannot be their own delegate");
    }
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return memberRepo.upsertAbsence({
    orgId: input.orgId,
    userId: member.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note ?? null,
  });
}

/** Clearing is idempotent: a member with no absence is simply left as is. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  assertCanManageAbsence(actor, member);

  await memberRepo.deleteAbsence(orgId, member.userId);
}

/**
 * The member's absence while it still matters: one that is running or has yet
 * to start. Once the end has passed it reads as `null`, the same as none set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:read", orgResource(orgId));

  const member = await requireActiveMember(orgId, userId);

  const absence = await memberRepo.findAbsence(orgId, member.userId);
  if (absence === null) return null;

  return Date.now() < toInstant(absence.endsAt) ? absence : null;
}

/**
 * Who stands in for `userId` at the instant `at` — the delegate of an absence
 * covering that instant (start inclusive, end exclusive), provided the
 * delegate is still an active member. `null` when the member is not away, has
 * named nobody, or the delegate has left.
 *
 * Deliberately one hop: the delegate's own absence is never consulted, so
 * delegation cannot chain. Scoped to `orgId` — an absence in one organization
 * says nothing about another.
 */
export async function resolveDelegate(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await memberRepo.findAbsence(orgId, userId);
  if (absence === null || absence.delegateUserId === null) return null;

  const instant = at.getTime();
  const away =
    toInstant(absence.startsAt) <= instant &&
    instant < toInstant(absence.endsAt);
  if (!away) return null;

  const delegate = await memberRepo.findMember(orgId, absence.delegateUserId);
  if (!delegate || delegate.status !== "active") return null;

  return delegate.userId;
}

/**
 * Turns a (user, org) pair into the `Actor` every service method takes. The
 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here.
 */
export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") return null;

  return { userId, orgId, role: member.role };
}

/**
 * Throws when applying `nextRole` to `memberId` would leave the organization
 * without an owner. Exported because both the demote and the remove path need
 * it, and the invariant must not be stated twice.
 */
export async function assertLastOwnerRetained(
  orgId: OrgId,
  memberId: MemberId,
  nextRole: Role,
): Promise<void> {
  if (nextRole === "owner") return;

  const member = await memberRepo.findMemberById(orgId, memberId);
  if (!member || member.role !== "owner") return;

  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: OWNER_SCAN_LIMIT,
    cursor: null,
  });

  const remaining = page.items.filter((row) => row.id !== memberId);
  if (remaining.length === 0) {
    throw new Error(
      "An organization must keep at least one owner; transfer ownership first",
    );
  }
}

/** A live membership in good standing; anything else reads as "no such member". */
async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
  return member;
}

/**
 * A member's own absence is theirs to manage. Anyone else's is an
 * administrative act on that member, gated by the same permission as a role
 * change so the two cannot drift apart.
 */
function assertCanManageAbsence(actor: Actor, member: Member): void {
  if (member.userId === actor.userId) return;
  assertCan(actor, "member:update_role", memberResource(member));
}

/** Epoch milliseconds, so timestamps of differing precision compare correctly. */
function toInstant(stamp: string): number {
  return new Date(stamp).getTime();
}
